    document.querySelectorAll('.lang-dd').forEach(function (dd) { var on = dd.querySelector('.lang-sw button.on'), cur = dd.querySelector('.lang-cur'); if (on && cur) { cur.innerHTML = on.querySelector('svg').outerHTML; cur.title = on.title; } });
