    if (cur) { var dd = cur.parentNode, op = !dd.classList.contains('open'); document.querySelectorAll('.lang-dd.open').forEach(function (x) { x.classList.remove('open'); x.querySelector('.lang-cur').setAttribute('aria-expanded', 'false'); }); dd.classList.toggle('open', op); cur.setAttribute('aria-expanded', op); return; }
